package com.xyz.question_bank_management_system.modules.source.mapper;
import com.xyz.question_bank_management_system.modules.source.entity.FileAsset; import org.apache.ibatis.annotations.*;
@Mapper public interface FileAssetMapper { @Insert("INSERT INTO file_asset(biz_type,biz_id,file_name,file_ext,mime_type,storage_type,storage_path,file_size,file_hash,uploaded_by,created_at,is_deleted) VALUES(#{bizType},#{bizId},#{fileName},#{fileExt},#{mimeType},#{storageType},#{storagePath},#{fileSize},#{fileHash},#{uploadedBy},NOW(3),0)") @Options(useGeneratedKeys=true,keyProperty="id") int insert(FileAsset e); @Update("UPDATE file_asset SET biz_id=#{bizId} WHERE id=#{id} AND is_deleted=0") int updateBizId(FileAsset e); @Select("SELECT * FROM file_asset WHERE id=#{id} AND is_deleted=0") FileAsset selectById(Long id); }
